    async def list_versions(
        self,
        *,
        region: str | None = None,
        version: str | None = None,
        page: int | None = None,
        page_size: int | None = None,
    ) -> ListVersionsResponse:
        """
        List available MongoDB® versions

        Args:
            region: The region you want to target
        """
        data = await self._client.request_json(
            "GET",
            self._client.path(
                "/mongodb/v1alpha1/regions/{region}/versions",
                region=self._client.region(region),
            ),
            params={"version": version, "page": page, "page_size": page_size},
        )
        return ListVersionsResponse.model_validate(data)

    async def list_versions_iter(
        self,
        *,
        region: str | None = None,
        version: str | None = None,
        page_size: int | None = None,
    ) -> AsyncIterator[Version]:
        """Iterate over every item of `list_versions`, page after page."""

        async def fetch(page: int) -> tuple[ListVersionsResponse, int | None]:
            response = await self._client.request(
                "GET",
                self._client.path(
                    "/mongodb/v1alpha1/regions/{region}/versions",
                    region=self._client.region(region),
                ),
                params={"version": version, "page": page, "page_size": page_size},
            )
            result = ListVersionsResponse.model_validate(response.json())
            return result, result.total_count

        async for entry in paginate(
            fetch,
            lambda page: page[0].versions or [],
            lambda page: page[1],
        ):
            yield entry

    async def list_versions_all(
        self,
        *,
        region: str | None = None,
        version: str | None = None,
        page_size: int | None = None,
    ) -> list[Version]:
        """Every item of `list_versions`, all pages read."""
        return [
            entry
            async for entry in self.list_versions_iter(
                region=region, version=version, page_size=page_size
            )
        ]
